import networkx as nx
import itertools

def get_all_perfect_matchings(n):
    all_edges = list(itertools.combinations(range(n), 2))
    all_pm = []
    for p in itertools.permutations(range(n)):
        pm = set()
        for i in range(0, n, 2):
            pm.add(tuple(sorted((p[i], p[i+1]))))
        all_pm.append(pm)

    # Unique PMs
    unique_pm = []
    seen = set()
    for pm in all_pm:
        f = tuple(sorted(list(pm)))
        if f not in seen:
            seen.add(f)
            unique_pm.append(pm)
    return unique_pm

def solve_small_n(n):
    pms = get_all_perfect_matchings(n)
    for a in range(1, n):
        for combo in itertools.combinations(pms, a):
            union_edges = set()
            for pm in combo:
                union_edges.update(pm)

            complement_edges = []
            for u in range(n):
                for v in range(u + 1, n):
                    if (u, v) not in union_edges:
                        complement_edges.append((u, v))

            G_comp = nx.Graph()
            G_comp.add_nodes_from(range(n))
            G_comp.add_edges_from(complement_edges)

            matching = nx.max_weight_matching(G_comp, maxcardinality=True)
            if len(matching) < n // 2:
                return a
    return n - 1

print(f"n=4: {solve_small_n(4)}")
print(f"n=6: {solve_small_n(6)}")
print(f"n=8: {solve_small_n(8)}")
